static unsigned int read_fault_calls;

static x_nucleo_ihm16m1_status_t motor_platform_read_fault_callback(
    bool *fault,
    int cmock_num_calls)
{
    (void)cmock_num_calls;

    read_fault_calls++;
    if (read_fault_calls == 1U) {
        *fault = true;
    } else {
        *fault = false;
    }

    return X_NUCLEO_IHM16M1_OK;
}

void setUp(void)
{
    read_fault_calls = 0U;
}

void tearDown(void)
{
}

void test_SF_003_01(void)
{
    bool fault = false;
    x_nucleo_ihm16m1_status_t status;

    motor_platform_read_fault_StubWithCallback(
        motor_platform_read_fault_callback);

    status = safety_platform_check_fault(&fault);
    TEST_ASSERT_EQUAL_INT(X_NUCLEO_IHM16M1_OK, status);
    TEST_ASSERT_TRUE(fault);

    /* The physical EN/FAULT input has cleared, but the safety latch must not. */
    fault = false;
    status = safety_platform_check_fault(&fault);
    TEST_ASSERT_EQUAL_INT(X_NUCLEO_IHM16M1_OK, status);
    TEST_ASSERT_TRUE(fault);

    motor_platform_enable_ExpectAndReturn(false, X_NUCLEO_IHM16M1_OK);
    status = safety_platform_disable();
    TEST_ASSERT_EQUAL_INT(X_NUCLEO_IHM16M1_OK, status);
}
